// Device topic namespace. Mirrors messaging/MeoTopics.java
// (meo-3-open-service/docs/mqtt_messaging.md).
module.exports = (function() {
    "use strict";

    var PREFIX = "meo/v1/device/";

    return {
        PREFIX: PREFIX,
        EVENT_WILDCARD: PREFIX + "+/event",
        REPLY_WILDCARD: PREFIX + "+/reply",

        command: function(deviceId) {
            return PREFIX + deviceId + "/command";
        },

        deviceIdFromTopic: function(topic) {
            if (typeof topic !== "string" || topic.indexOf(PREFIX) !== 0) { return null; }
            var end = topic.indexOf("/", PREFIX.length);
            return end > PREFIX.length ? topic.substring(PREFIX.length, end) : null;
        }
    };
}());
